                case "tiny-town":ids=tiny_town;break;
                case "tiny-dungeon":ids=tiny_dungeon;break;
                case "tiny-factory":ids=tiny_factory;break;
                case "tiny-battle":ids=tiny_battle;break;
                default:throw new System.ArgumentException("Unknown imported sheet");
            }
            return new Sprite("Art/"+pack+".hsprites",ids[tile]);
        }
    }
}
